import test from 'node:test';import assert from 'node:assert/strict';
import {chapterWorlds,chapterSites,chapterFlags,normalizeChapter,learnedDigging,chapterAvailable,chapterCanVisit,chapterView,chapterAction,chapterNext,clearChapterGround,chapterArt,chapterArtKeys} from '../src/adventures.js';
import {pathfind} from '../src/navigation.js';import {objects,materials} from '../src/data.js';import {getJournalEntries} from '../src/journal.js';
test('Explore and Adaptive can start anytime; Guided needs both actual digging and prepared pad',()=>{const s=normalizeChapter();assert.ok(chapterAvailable('explore',s,false));assert.ok(chapterAvailable('adaptive',s,false));for(const dug of [false,true]){assert.equal(chapterAvailable('guided',s,dug),false);assert.ok(!chapterView(s,'desk','guided',dug).actions.some(([,a])=>a==='start'));}assert.equal(chapterAction(s,'unlock-pad','guided',false).chapter.rocketReady,false);const ready=chapterAction(s,'unlock-pad','guided',true).chapter;assert.equal(chapterAvailable('guided',ready,true),false);ready.elevatorCleared=true;assert.ok(chapterAvailable('guided',ready,true));assert.equal(chapterAvailable('guided',ready,false),false);assert.equal(chapterAction(s,'start','guided',false).travel,null);assert.ok(learnedDigging(new Set(['dig-quartz'])));assert.ok(!learnedDigging(new Set(['grounds-dig'])));});
test('all chapter stations and returns have reachable approaches on side-view maps',()=>{for(const [zone,z]of Object.entries(chapterWorlds))for(const o of objects.filter(o=>o.zone===zone))assert.ok(pathfind(z.spawn,[o.x-65,o.y+55],zone).length,o.id);assert.equal(chapterCanVisit('chapterMoon','explore',normalizeChapter(),false),false);});
test('collect-test-build clues and two guarded machines gate the complete chapter',()=>{let s=normalizeChapter();for(const key of ['station','tested','machine1','machine2','energy','finished','guard1'])assert.equal(chapterAction(s,'do:'+key).chapter[key],false,key);for(const key of chapterFlags){assert.equal(chapterNext(s).page,key);const r=chapterAction(s,'do:'+key);assert.ok(r.chapter[key],key);s=r.chapter;}assert.ok(s.finished);assert.equal(s.quartz,true);assert.equal(s.iron,true);assert.ok(chapterCanVisit('chapterMoon','explore',s,false));const repeated=chapterAction(s,'repeat:guard1').chapter;assert.deepEqual(repeated,s);assert.match(chapterView(s,'guard1').text,/spins and retreats/);assert.match(chapterView(s,'guard2').text,/puff/);assert.match(chapterView(normalizeChapter(),'guard1').text,/hostile/);assert.match(chapterView(s,'finished').text,/withdraw/);});
test('replay resets only chapter mission and tunnels while retaining rocket readiness',()=>{const s=normalizeChapter({rocketReady:true,started:true,finished:true,station:true,cleared:{chapterEarth:['1,4','1,4','999,999','bad'],chapterMoon:['3,5']}});assert.deepEqual(s.cleared.chapterEarth,['1,4']);const r=chapterAction(s,'restart');assert.equal(r.chapter.rocketReady,true);assert.equal(r.chapter.finished,false);assert.deepEqual(r.chapter.cleared.chapterMoon,[]);clearChapterGround(r.chapter,'chapterEarth',300,250);clearChapterGround(r.chapter,'chapterEarth',300,250);assert.equal(r.chapter.cleared.chapterEarth.length,1);assert.deepEqual(normalizeChapter(JSON.parse(JSON.stringify(r.chapter))),r.chapter);});
test('native choices fit six buttons including listen/home; art and factual labels distinguish fiction',()=>{for(const page of ['desk','pad','replay-confirm',...chapterFlags])for(const s of [normalizeChapter(),normalizeChapter(Object.fromEntries(chapterFlags.map(k=>[k,true])))]){const v=chapterView(s,page);assert.ok(v.actions.length+2<=6,page);assert.ok(chapterArtKeys.includes(v.art));assert.ok(chapterArt(v.art).includes('viewBox="0 0 340 210"'));}assert.match(chapterView(normalizeChapter(),'quartz').text,/fictional/);assert.match(chapterView(normalizeChapter(),'energy').text,/Moon nights are long/);});
test('journal milestones reflect actions, persist and point to replayable locations',()=>{const empty=getJournalEntries('adventures',new Set(),new Set(),objects,materials,{}, {},{},normalizeChapter());assert.equal(empty.length,0);const s=chapterAction(normalizeChapter(),'do:quartz').chapter;const entries=getJournalEntries('adventures',new Set(),new Set(),objects,materials,{}, {},{},s);assert.equal(entries.length,1);assert.equal(entries[0].target,'chapterEarth-quartz');assert.match(entries[0].fact,/fictional/);});
